// clear the slice without re-allocating.
// http://stackoverflow.com/questions/16971741/how-do-you-clear-a-slice-in-go
//   suggests this could be a memory leak, but we might as well keep the memory for the channel until it closes,
//	at which point the recving slice stops being used and should be garbage collected
ch.recving = ch.recving[:0] // make([]byte, 0, ch.desc.RecvBufferCapacity)

patches.new:
// Keep small receive buffers, but release completed large messages.
// Otherwise every peer/channel pins its largest historical message.
if cap(ch.recving) > 256*1024 {
	ch.recving = make([]byte, 0, ch.desc.RecvBufferCapacity)
} else {
	ch.recving = ch.recving[:0]
}

