for {
	if !peer.IsRunning() || !memR.IsRunning() {
		return
	}
	if ps, ok := peer.Get(types.PeerStateKey).(PeerState); ok {
		peerState = ps
		break
	}
	// A peer can disconnect before consensus installs its state.
	select {
	case <-time.After(PeerCatchupSleepIntervalMS * time.Millisecond):
	case <-peer.Quit():
		return
	case <-memR.Quit():
		return
	}
}

